INSERT INTO `university` (`id`, `name`, `abbrevation`, `description`, `accreditation`, `types`, `email`, `website`, `phone`, `address`, `studentAmount`, `map`, `cityId`, `provinceId`, `status`, `partner`, `featured`, `popularity`, `logo`, `banner`, `admissionBanner`, `galleryBanner`, `companyPartnerDescription`, `companyPartnerLogo`, `addressOthers`, `slug`, `createdAt`, `createdBy`, `updatedAt`, `updatedBy`, `deletedAt`, `deletedBy`) VALUES
	(1, 'Universitas Lintas Internasional Indonesia', 'IULI', 'International University Liaison Indonesia adalah sebuah universitas swasta yang didirikan pada tahun 2014, oleh pakar penerbangan Dr.-Ing. Ilham Akbar Habibie, MBA, berdasarkan SK DIKTI No. 425/E/02014. Kampus International University Liaison Indonesia berada di daerah The Breeze, BSD City, Serpong, Tangerang Selatan, Banten. Universitas ini merupakan hasil kerjasama antara konsorsium European University Consortium - EUC dan IULI Foundation. Yayasan International University Liaison Indonesia – IULI sendiri telah mendapatkan lisensi dan terdaftar pada Kementrian Hukum dan HAM (Hak Asasi Manusia) Republik Indonesia dengan NPWP: 31.698.854.2-411.000.', 'C', 'SWASTA', 'info@iuli.ac.id', 'www.iuli.ac.id', '85212318000', 'MyRepublic Plaza The Breeze, BSD City 15345', 474, 'https://goo.gl/maps/C6LQhFkVuxjc2jjw9', 22, 3, 'PUBLISHED', 'Y', 'N', 6, 'university/logo/1575871588276-c4dcd191.png', 'university/banner/1575857707012-5d98fe60.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-lintas-internasional-indonesia', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(2, 'Universitas Sampoerna', NULL, NULL, NULL, 'SWASTA', NULL, 'www.sampoernauniversity.ac.id', '(021) 50 222 234; 0821 62 800 800', 'L\'Avenue, Jln. Raya Pasar Minggu, Kav. 16, Pancoran (11,88 km)\r\nJakarta 12510', 408, NULL, 42, 6, 'PUBLISHED', NULL, 'N', 7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-sampoerna', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(3, 'Universitas Pembangunan Jaya', 'UPJ', 'Universitas Pembangunan Jaya (UPJ) adalah sebuah perguruan tinggi swasta di daerah Bintaro yang berdiri pada tahun 2011 dan didukung oleh kelompok usaha Pembangunan Jaya. Kelompok usaha Pembangunan Jaya memiliki 17 usaha yang bergerak dibidang properti, manufaktur, konsultan manajemen, konsultan desain, kontraktor, pariwisata/rekreasi, trading, mekanikal & elektrikal dan pendidikan. Kelompok usaha Pembangunan Jaya memiliki pengalaman lebih dari 50 tahun dalam mengelola sektor usaha dan beritikad untuk mengabdikan sebagian dari kegiatan usaha induknya ke pendidikan dalam membangun sumber daya manusia Indonesia yang lebih berkualitas. Itikad ini, telah diwujudkan dengan mendirikan Yayasan Pendidikan Jaya sejak 3 September 1991. Yayasan Pendidikan Jaya telah menaungi penyelenggaraan pendidikan taman kanak-kanak, pendidikan dasar dan pendidikan menengah yaitu TK/SD/SMP/SMA Sekolah Pembangunan Jaya I di Bintaro sejak tahun 1992, TK/SD/SMP/SMA Global Jaya tahun 1995, dan TK dan SD Sekolah Pembangunan Jaya II di Surabaya sejak tahun 2006. Berangkat dari keberhasilan dalam pengelolaan pendidikan dasar dan menengah lebih dari 10 tahun, Yayasan Pendidikan Jaya berinisiatif melangkah lebih jauh untuk membentuk institusi pendidikan tinggi yang diberi nama Universitas Pembangunan Jaya. Melalui perjalanan yang cukup panjang dan berliku akhirnya Universitas Pembangunan Jaya berhasil mengantongi ijin penyelenggaran pendidikan tinggi pada tahun 2011.Berbekal moto "Integrity, professionalism, and Entrepreneurship", UPJ adalah sebuah rumah belajar di mana di mana mahasiswa dapat menimba ilmu dan mengembangkan diri untuk menjadi insan berintegritas, profesional, kreatif, inovatif, dan berjiwa entrepreneur.\n\nAwal mula penyelenggaraan pendidikan tinggi, UPJ menempati sebuah ruko yang berada di kawasan Bintaro Jaya. Seiring dengan pertumbuhan mahasiswa dan kebutuhan pengembangan kampus yang lebih baik, dengan dukungan penuh dari kelompok usaha Pembangunan Jaya dan Yayasan Pendidikan Jaya, UPJ menempati gedung baru yang juga berada di kawasan Bintaro Jaya sejak Juni 2015. Keseriusan kelompak usaha Pembangunan Jaya dan yayasan Pendidikan Jaya dalam mendukung UPJ ditunjukkan dengan komitmen lahan seluas 15 hektar yang dialokasikan untuk pengembangan UPJ 20 tahun ke depan.', 'B', 'SWASTA', 'info@upj.ac.id', 'upj.ac.id', '(021)7455555- (021) 29045405', 'Jl. Cendrawasih Raya Blok B7/P Bintaro Jaya, Sawah Baru, Ciputat, Tangerang Selatan 15413', 1806, 'https://www.bing.com/maps?osid=ba205f59-d60e-41e0-87d2-74dc1c2d4a9c&cp=-6.286892~106.660412&lvl=13&imgid=091599b4-be80-40a0-888a-f099f86d45c4&v=2&sV=2&form=S00027', 24, 3, 'PUBLISHED', 'Y', 'N', 1, 'university/logo/1575858148459-323da58c.png', 'university/banner/1575858152982-bfd03da0.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-pembangunan-jaya', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(4, 'Esmod', NULL, 'ORIGINS\n\nAlexis Lavigne, inventor of the mannequin and the supple measuring tape, founded ESMOD in 1841. It is the world’s first fashion school and the birthplace of several patented design methods.\n\nIbu Hartini Hartarto brought ESMOD to Jakarta in 1996, having observed the skill and fashion interest in the youth of Indonesia. By launching ESMOD Jakarta she opened an avenue to professional fashion education and an opportunity to compete in the global market.\n\nESMOD is now the worldwide fashion education leader, present in 15 countries worldwide, with 23 different schools.\n\nESMOD JAKARTA’S DNA\n\nWe uphold the rigorous professional standard that is set by ESMOD throughout all its locations across the world. And we encourage young designers to adapt it to the rich cultural heritage of Indonesian culture, by using techniques to preserve and innovate traditional costumes and textile prints.\n\nESMOD Jakarta places fashion in a wider context. That’s why we focus on both fashion and business, preparing both the future trend-defining fashion designers as the future fashion entrepreneurs. In our fashion design programs we divide time equally between design and pattern drafting (Stylisme & Modelisme), and provide you with the skills needed to bring a collection from start to end.', 'A', 'SWASTA', 'info@esmodjakarta.com', 'esmodjakarta.com', '021-7659181; 021-7659182', 'JL. Asem Dua No. 3-5 Cipete, Jakarta Selatan, Jakarta 12420', 150, 'https://goo.gl/maps/msewseWm8V9yoBsp7', 42, 6, 'PUBLISHED', 'Y', 'N', 4, 'university/logo/1575861483005-3bd9ddf5.png', 'university/banner/1575861487028-a7278d24.jpg', NULL, NULL, NULL, NULL, '[]', 'esmod', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(5, 'Raffles', NULL, NULL, 'A', 'SWASTA', NULL, NULL, '(+62) 21 2555 6738', 'Citywalk Sudirman 6th Floor, Jl. K.H. Mas Mansyur Jakan No.121, RT.10/RW.11, Karet Tengsin, Kota Jakarta Pusat, Daerah Khusus Ibukota Jakarta 10210', NULL, NULL, 41, 6, 'PUBLISHED', NULL, 'N', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'raffles', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(6, 'Universitas Katholik Indonesia Atma Jaya', 'UNIKA Atma Jaya', '<p><font size="2"><span class="TextRun SCXW89992033 BCX0" lang="EN-US"><span class="SpellingError SCXW89992033 BCX0">Unika Atma Jaya berdiri pada tanggal 1 Juni 1960, didirikan oleh Yayasan Atma Jaya. Pada Juni 1952 para Uskup se-Jawa mengadakan pertemuan untuk membentuk suatu perguruan tinggi Katolik. P</span></span><span>ada tanggal 1 Juni 1960 d</span><span>i Jakarta gagasan itu terwujud sejak didirikannya Yayasan Atma Jaya oleh sekelompok cendekiawan muda mereka&#160; diataranya, Ir. J.P. Cho, Drs. Lo Siang Hien-Ginting, Drs. Goei Tjong Tik, I.J. Kasimo, J.B. Legiman, S.H., Drs. F.X. Seda, Pang Lay Kim, Tan Bian Seng, Anton M. Moeliono, St. Munadjat Danusaputro, J.E. Tan, Ben Mang-Reng Say.</span></font></p><p><span><font size="2">Pada tahun-tahun awal, Unika Atma Jaya dibantu oleh para suster Ursulin, dengan&#160; menyediakan ruang kuliah di kompleks persekolahan Ursulin, di Jalan Lapangan Benteng Utara dan kompleks Santa Theresia, Menteng.</font></span></p><p><font size="2"><span class="TextRun SCXW136558284 BCX0" lang="EN-US"></span><span>Sejak tahun 1967, Atma Jaya berangsur-angsur menempati kampus di Jalan Sudirman yang terkenal dengan nama kampus Semanggi. Selanjutnya menempati kampus Pluit, di Jakarta Utara untuk Fakultas Kedokteran (FK), Rumah Sakit Atma Jaya (RSA), dan Rumah Duka Atma Jaya.</span></font></p><p><span><font size="2">Unika Atma Jaya memiliki delapan fakultas dengan dua puluh satu program studi untuk Program Sarjana (S1) dan tujuh program magister untuk Program Pasca Sarjana.</font></span></p>', 'A', 'SWASTA', 'pr@atmajaya.ac.id', 'www.atmajaya.ac.id', '(62-21) 5727615, 5703306, 5708823', 'Jl. Jenderal Sudirman 51, Jakarta 12930', 10052, 'https://goo.gl/maps/sLunk8zMWj68YaDL7', 42, 6, 'PUBLISHED', 'Y', 'N', 2, 'university/logo/1575857197972-73b76ff3.jpg', 'university/banner/1575857202618-165e1cd5.jpg', NULL, NULL, NULL, NULL, '[{"name":"Kampus Pluit","address":"Jl. Pluit Raya No.2, RT.21/RW.8, Penjaringan, Kec. Penjaringan, Kota Jkt Utara, Daerah Khusus Ibukota Jakarta 14440","phone":"(021) 6693168","fax":""},{"name":"Kampus BSD","address":"Jl. Raya Cisauk Lapan, Sampora, Kec. Cisauk, Tangerang, Banten 15345","phone":"(021) 80827200","fax":""}]', 'universitas-katholik-indonesia-atma-jaya', '2019-12-06 05:23:33', '0', '2019-12-10 09:35:01', '0', NULL, NULL),
	(7, 'Universitas Pelita Harapan', 'UPH', '<p><span class="TextRun SCXW14267512 BCX0" lang="EN-US"><span class="SpellingError SCXW14267512 BCX0"><font size="2">Universitas Pelita Harapan didirikan pada bulan September 1994, pendiri dari UPH yaitu Ir. Johanes Oentoro dan Dr. (HC) James Riady. Pada tanggal 27 September 1994 perkuliahan dimulai di Menara Asia, yang awalnya menempati gedung sementara di Gedung Lippo Bank, Kedoya, Jakarta, kemudian pindah ke gedung Menara Asia di kota mandiri Lippo Karawaci, Tangerang. Perkuliahan dimulai dengan kurang lebih 250 mahasiswa di 3 fakultas dan 8 jurusan sementara gedung UPH Tower sedang berjalan.</font></span></span></p><p><font size="2"><span>Pada tahun 1995, Yayasan Pelita Harapan membuka Akademi Pariwisata dengan jurusan Manajemen Perhotelan dan Manajemen Usaha Wisata serta Fakultas Ilmu Komunikasi. Di tahun yang sama semua kegiatan perkuliahan dipindahkan ke gedung UPH Tower. Sejalan dengan pertumbuhan jumlah mahasiswa dan pertambahan jurusan pembangunan gedung kuliah pun bertambah.</span><br></font></p><p><font size="2"><span>Pada tahun 2006, Universitas Pelita Harapan membuka kelas internasional bagi mereka yang ingin mendapatkan gelar sarjana di indonesia.&#160; Universita Pelita Harapan membuka program S2 Master di kawasan Semanggi, Jakarta.&#160; Pada tahun 2007 Universitas Pelita Harapan membuka cabang&#160; di luar Jabodetabek, yaitu di Surabaya, Jawa Timur dengan program sarjana S-1 dan 2 program S-2 master. Universitas Pelita Harapan menerapkan secara langsung teknologi ke dalam sistem belajar-mengajar.</span><br></font></p><p><font size="2"><span>Sejak awal berdirinya, penjaminan mutu Universitas Pelita Harapan menjadi perhatian utama dan dilaksanakan oleh setiap fakultas, program studi, dan unit kerja pendukung.&#160; Memberikan pendidikan terbaik kepada mahasiswa merupakan prioritas bagi pendiri Universitas Pelita Harapan.</span><br></font></p><p><font size="2"><span>Sejak tahun 2004, UPH mulai mengembangkan sistem manajemen mutu berbasis ISO 9001:2000 dan mulai mempersiapkan diri untuk sertifikasi. Pada tahun 2006 dibentuk Direktorat Penjaminan Mutu UPH yang dipimpin oleh seorang Direktur Penjaminan Mutu. Sertifikasi ISO 2001:2000 akhirnya diperoleh pada tanggal 23 April 2008 dan diperpanjang pada tanggal 3 Juni 2010. Sejalan dengan perkembangan sistem penjaminan mutu pendidikan tinggi di Indonesia dan juga perkembangan UPH yang cukup pesat, maka UPH juga membangun dan mengembangkan Sistem Penjaminan Mutu Internal yang terintegrasi dengan Sistem Penjaminan Mutu Eksternal.&#160;</span><br></font></p><p><font size="2"><span>Pada tanggal 2 Februari 2015, dibentuk Lembaga Pengembangan dan Penjaminan Mutu Pendidikan atau dikenal dengan LP2MP. LP2MP dipimpin oleh seorang Ketua yang bertanggung jawab langsung kepada Rektor, dan merupakan perluasan peran Direktorat Penjaminan Mutu. Kesungguhan UPH dalam upaya peningkatan mutu berkelanjutan tampak dengan adanya peningkatan peringkat akreditasi berbagai program studi yang ada di UPH.</span><br></font></p><p><font size="2"><span class="NormalTextRun  BCX0 SCXW145251119"><span class="TextRun  BCX0 SCXW145251119" lang="EN-US"><span class="NormalTextRun  BCX0 SCXW145251119">Sejak tahun 2015 hingga kini sudah ada 7 program studi terakreditasi A. Universitas Pelita Harapan menjadi satu di antara 17 perguruan tinggi&#160; indonesia yang masuk ke dalam peringkat 400 perguruan tinggi terbaik di Asia versi QS Asia University Rangkings 2018.&#160;</span></span></span><span>Komitmen peningkatan mutu berkelanjutan ini senantiasa dipegang oleh UPH, agar ke depan dapat memberikan layanan pendidikan tinggi yang semakin unggul bagi mahasiswa, dan berkontribusi bagi masyarakat, bangsa dan negara Indonesia.</span></font></p>', 'B', 'SWASTA', 'undergraduate.admission@uph.edu', 'www.uph.edu', '(021) 546 0901\r\n(021) 547 0901', 'Jl. MH. Thamrin Boulevard 1100, Klp. Dua, Karawaci, Tangerang, Banten 15811', 18144, 'https://goo.gl/maps/ffwGqNTrS9PcgTVF6', 23, 3, 'PUBLISHED', 'N', 'N', 6, 'university/logo/1575866463456-dd25ac78.png', 'university/banner/1575866471267-085cf6bf.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-pelita-harapan', '2019-12-06 05:23:33', '0', '2019-12-10 08:48:37', '0', NULL, NULL),
	(8, 'Universitas Matana', NULL, '<div class="OutlineElement Ltr  BCX0 SCXW100048644"><p class="Paragraph SCXW100048644 BCX0" lang="EN-US"><span><font size="2">Universitas Matana adalah sebuah uniersitas yang didirikan pada bulan Agustus 2014 oleh Paramount Enterprise. Universitas Matana mulau beroperasi dengan 10 Program Studi dan berlokasi di Gedung Ara Center, Matana Tower.</font></span></p><p class="Paragraph SCXW100048644 BCX0" lang="EN-US"><font size="2"><span>Universitas Matana mendidik calon-calon eksekutif bisnis dan pemimpin masa depan dalam berbagai bidang ilmu, dengan memberi penekanan yang seimbang antara pengetahuan akademik, pengembangan kemampuan soft skills dan pembentukan karakter mahasiswa yang bersifat&#160; menyeluruh. Maka dari itu lulusan Universitas Matana menguasai pengetahuan dan keterampilan tertentu serta memiliki Intergritas, Penatalayanan, serta Saling Menghargai.</span><br></font></p><p class="Paragraph SCXW100048644 BCX0" lang="EN-US"><font size="2">Seluruh pengalaman akademik yang didapatkan oleh mahasiswa Universitas Matana difokuskan untuk kapasitas belajar yaitu kapasitas intelektual, sosial, entreprenurial, dan spiritual.&#160;Sarjana Universitas Matana adalah manusia terdidik dan trampil karena selain memiliki budaya research dan keilmuan, juga seimbang dengan nilai moral dan keseganan kepada Tuhan.</font></p></div>', 'C', 'SWASTA', 'info@matanauniversity.ac.id', 'matanauniversity.ac.id', '(+62) 29232999', 'Matana University Tower.\r\nJl. CBD Barat Kav. 1. Gading Serpong\r\nTangerang - 15810, Indonesia.', 974, 'https://goo.gl/maps/3hLuGkC5kYgrDuoY7', 23, 3, 'PUBLISHED', 'Y', 'N', 5, 'university/logo/1575856267534-8542479f.jpg', 'university/banner/1575856273192-0f4d2cd1.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-matana', '2019-12-06 05:23:33', '0', '2019-12-10 08:50:37', '0', NULL, NULL),
	(9, 'Universitas Paramadina', NULL, '<div class="OutlineElement Ltr SCXW198420132 BCX0"><p class="Paragraph SCXW198420132 BCX0" lang="EN-US"><font size="2"><span class="TextRun SCXW198420132 BCX0" lang="EN-US"><span class="NormalTextRun SCXW198420132 BCX0">Yayasan Paramadina-Mulya mendirikan universitas yang dikukuhkan tanggal 27 Februari 1995, No. 188. Sejak saat itu gagasan untuk mendirikan universitas mulai di kembangkan. Pada tanggal 10 Januari 1998 diresmikan berdirinya Universitas Paramadina-Mulya.</span></span></font></p><p class="Paragraph SCXW198420132 BCX0" lang="EN-US"><span>Yayasan Paramadina-Mulya merupakan gabungan dari 2 yayasan yaitu, yayasan Wakaf Paramadina dan Yayasan Pondok Mulya. yang masing-masing bergerak di bidang pendidikan dan berorientasi pada nilai-nilai islam.</span><br></p></div><div class="OutlineElement Ltr SCXW198420132 BCX0"><p class="Paragraph SCXW198420132 BCX0" lang="EN-US"><span>Yayasan Paramadina-Mulya dibubarkan dan kepemilikan serta pengelolaan Universita Paramadina-Mulya diserahkan kepada yayasan Wakaf Paramadina dengan Akta Notaris Harun Kamil, SH. No. 20 A. pada tanggal 20 Maret 2002.</span><br></p><p class="Paragraph SCXW198420132 BCX0" lang="EN-US"><span>Sebagai tindak lanjut penyerahan kepemilikan dan pengelolaan tersebut, Yayasan Wakaf Paramadina dengan surat keputusan no. SK-10/DP-YWP/X/2002 tanggal 15 Oktober 2002 mengubah nama Universitas Paramadina-Mulya menjadi Universitas Paramadina. Program Fellowship yang mulai digulirkan tahun 2008 berhasil mendongkrak citra universitas.</span><br></p></div>', 'B', 'SWASTA', 'info@paramadina.ac.id', 'www.paramadina.ac.id', '(+62) 2179181188', 'Jl. Gatot Subroto No.Kav. 97, RT.4/RW.4, Mampang Prpt., Kec. Mampang Prpt., Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12790', 2448, 'https://goo.gl/maps/UxjBxwrTfit7YjfV9', 23, 3, 'PUBLISHED', 'N', 'N', 9, 'university/logo/1575865230789-8134a4d3.jpg', 'university/banner/1575865235056-6e77e6dd.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-paramadina', '2019-12-06 05:23:33', '0', '2019-12-10 08:43:07', '0', NULL, NULL),
	(10, 'Universitas Bakrie', NULL, '<p><span>Pada tahun 2006 STIE Bakrie School of Management (BSM) berdiri yang sebelumnya bernama STIE Mulia Persada. P</span><span>ada saat itu Bakrie School of Management hanya memiliki 1 program studi, yaitu Management.</span></p><p><span>Di tahun berikut tepatnya pada&#160; tahun 2007, STIE Bakrie School of Management memiliki 2 program studi yaitu program studi Management dan program studi Akuntansi.</span><br></p><p><span>Yayasan Pendidikan Bakrie (YPB) menetapkan pendirian Universitas Bakrie berdasarkan Surat Keputusan Menteri Pendidikan Nasional Republik Indonesia</span><br></p><p><span>Pada Juli 2009.&#160;</span><span>Nomor 102/D/0/2009 menggantikan status Bakrie School of Management (BSM) yang semula STIE menjadi Universitas dengan tambahan program studi baru.</span><br></p><p><span>Pada tanggal 9 Agustus 2010, Universitas Bakrie diresmikan oleh Menteri Pendidikan Nasional Republik Indonesia Prof. Dr. Ir. H. Mohammad Nuh, DEA.</span><br></p>', 'B', 'SWASTA', 'admisi@bakrie.ac.id', 'www.bakrie.ac.id', '(021) 526 1448', 'Kawasan Rasuna Epicentrum, Jl. H. R. Rasuna Said No.Kav. C-22, RT.2/RW.5, Karet Kuningan, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12940', 3465, 'https://goo.gl/maps/E4tcoYL5RxdqsN1H7', 42, 6, 'PUBLISHED', 'N', 'N', 8, 'university/logo/1575864516633-f51bea68.jpg', 'university/banner/1575864520060-8dd3e70c.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-bakrie', '2019-12-06 05:23:33', '0', '2019-12-10 08:42:06', '0', NULL, NULL),
	(11, 'Universitas Pradita', NULL, NULL, NULL, 'SWASTA', 'info@pradita.ac.id', 'pradita.ac.id', '(021) 55689999', 'Tower 1, Scientia Business Park, Jl. Gading Serpong Boulevard No.1, Curug Sangereng, Kelapa Dua, Tangerang, Banten 15810', NULL, 'https://goo.gl/maps/xn9NGDtM587yn6DXA', 23, 3, 'PUBLISHED', NULL, 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-pradita', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(12, 'Universitas Multimedia Nusantara', 'UMN', 'Universitas ini diresmikan pendiriannya pada tanggal 20 November 2006. Fokus pendidikannya adalah dalam bidang teknologi informasi dan komunikasi (ICT). Universitas ini didirikan oleh Kelompok Kompas Gramedia, sebuah kelompok usaha terkemuka yang bergerak di bidang media massa, penerbitan, percetakan, toko buku, hotel, dan jasa pendidikan. Sebagai pendiri, Kompas Gramedia mendukung UMN tidak saja dalam hal penyediaan sarana fisik tetapi juga tenaga pengajar dan sarana kerja magang bagi mahasiswanya.\nUniversitas Multimedia Nusantara didirikan atas prakarsa Dr. (HC) Jakob Oetama, perintis Kompas Gramedia. Prakarsa tersebut selanjutnya direalisasikan oleh jajaran pimpinan Kompas Gramedia, yaitu: Agung Adiprasetyo (CEO Kompas Gramedia), Teddy Surianto (Business Development), jajaran Board of Directors Kompas Gramedia dan panitia pendiri yang dipimpin oleh Dr. Ir. P.M. Winarno (Ketua) dan Ir. Budi Susanto, M.M. (Wakil Ketua). Selanjutnya pada tanggal 25 November 2005, izin operasional Universitas Multimedia Nusantara diterbitkan oleh Menteri Pendidikan Nasional RI dan pada tanggal 20 November 2006, UMN secara resmi diluncurkan dalam sebuah acara di Hotel Santika, Jakarta dan diresmikan oleh Dr. Ir. Dodi Nandika Sekretaris Jenderal Kementerian Pendidikan Nasional. Rektor UMN dijabat oleh Prof. Yohanes Surya, Ph.D.(2006-2011), seorang fisikawan yang terkenal dengan kiprahnya membawa Tim Olimpiade Fisika Indonesia (TOFI) ke ajang Olimpiade Fisika Internasional.\n\nSebelum kampus definitifnya berdiri, UMN berkantor dan beroperasi di Gedung Wisma BNI 46, selanjutnya pada bulan Agustus 2008 pindah ke Plaza Summarecon Serpong. Pada tanggal 5 September 2008, dilakukan pemancangan tiang pancang di lokasi kampus definitifnya dan mulai tahun akademik 2009/2010 UMN menempati kampus baru di lahan seluas 8 hektare yang terletak di kawasan Scientia Garden, Summarecon Serpong, Tangerang, Banten. Kampus UMN tahap pertama ini terdiri dari gedung perkuliahan (5 lantai) dan gedung rektorat (8 lantai), luas total gedung adalah 17.000 m2.\n\nPada tanggal 25 Maret 2011, Dr. Ninok Leksono menggantikan Prof. Yohanes Surya, Ph.D. sebagai Rektor Universitas Multimedia Nusantara. Dr. Ninok Leksono adalah wartawan senior Harian Kompas dan anggota Dewan Riset Nasional (DRN).\n\nPada tanggal 29 April 2011, Yayasan Multimedia Nusantara memulai pembangunan kampus tahap 2, berupa 5 menara bergaya ecofriendly. Setelah 5 tahun berdiri, tanggal 26 November 2011, UMN melaksanakan wisuda perdana yang diikuti oleh 75 orang wisudawan.  Mereka terdiri atas 6 mahasiswa akuntansi, 16 orang dari desain komunikasi visual, 25 orang dari ilmu komunikasi, 3 orang dari sistem informasi, 5 orang dari sistem komputer, 17 orang dari teknik informatika, dan 3 orang dari manajemen.', 'A', 'SWASTA', 'admisi@umn.ac.id', 'www.umn.ac.id', '(+62)2154220808', 'Jl. Scientia Boulevard, Gading, Serpong, Tangerang, Banten 15227', 8191, 'https://goo.gl/maps/nq57cGcBQh61sAQh7', 23, 3, 'PUBLISHED', 'N', 'N', 11, 'university/logo/1575872866490-7774d360.jpg', 'university/banner/1575872870618-8152af48.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-multimedia-nusantara', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(13, 'Universitas Bina Nusantara', 'Binus', 'Universitas Bina Nusantara pada awalnya berasal dari sebuah institusi pelatihan komputer Modern Computer Course yang didirikan pada 21 Oktober 1974. Seiring dengan perkembangan, Modern Computer Course kemudian berkembang menjadi Akademi Teknik Komputer (ATK) pada 1 Juli 1981. Akademi ini menawarkan pendidikan manajemen informatika dan teknik informatika. Tiga tahun kemudian pada 13 Juli 1984 ATK mendapatkan status terdaftar dan berubah menjadi AMIK Jakarta. Pada 1 Juli 1985, AMIK membuka kursus di bidang komputerisasi akuntansi. AMIK mulai menggunakan nama Bina Nusantara pada 21 September 1985.\n\nAMIK mendapatkan penghargaan akademi komputer terbaik dari Menteri Pendidikan dan Kebudayaan pada 17 Maret 1986. AMIK Bina Nusantara kemudian membentuk STMIK (Sekolah Tinggi Manajemen Informatika dan Komputer) Bina Nusantara pada 1 Juli 1986. Institusi ini kemudian menawarkan program studi sarjana (S1) di bidang manajemen informatika dan teknik informatika.\n\nPada 9 November 1987 AMIK Bina Nusantara bergabung dengan STMIK Bina Nusantara membentuk satu institusi pendidikan yang menawarkan program studi diploma (D3) dan strata 1 (S1). STMIK Bina Nusantara memperoleh status disamakan untuk semua program studi pada 18 Maret 1992. STMIK Bina Nusantara kemudian membuka program studi pascasarjana manajemen sistem informasi, pertama di Indonesia pada 10 Mei 1993.\n\nUniversitas Bina Nusantara kemudian didirikan pada 8 Agustus 1996. STMIK Bina Nusantara kemudian bergabung dengan Universitas Bina Nusantara pada 20 Desember 1998. Saat ini, Universitas Bina Nusantara memiliki program pendidikan: Sekolah Sistem Informasi, Sekolah Teknik Informatika, Fakultas Teknik, Sekolah Bisnis dan Manajemen, Fakultas Ekonomi dan Komunikasi, Sekolah Desain, Fakultas Humaniora, Magister Teknik Informatika, Magister Manajemen Sistem Informasi, Magister Manajemen (Sekolah Bisnis), dan Doktor Riset Manajemen.\n\nPada 23 Oktober 2014, Universitas Binus meluncurkan kampus terbarunya dengan mengadakan grand launching Binus University di Alam Sutera, Serpong, Tangerang. Kampus baru ini berupa gedung 22 lantai dan menerapkan konsep green campus, bangunan yang ramah lingkungan dengan pemakaian fasilitas-fasilitas hemat energi. Kampus seluas 25 ribu meter persegi tersebut didesain oleh arsitek Indonesia, yaitu Budiman. Kampus Alam Sutera memiliki empat program studi utama. Keempatnya adalah computer science, school of design, school business and management, serta information system.\n\nPada 29 April 2015, Binus dan PT. Summarecon Agung Tbk. melakukan penandatanganan perjanjian pembangunan Kampus baru di Summarecon Bekasi. Kampus ini direncanakan akan dibangun diatas lahan seluas 36.400 m2 di Jalan Lingkar Bulevar Kota Summarecon Bekasi. Untuk tahap awal, pada Maret 2016 Binus akan membuka fasilitas perkuliahan online learning: BINUS UNIVERSITY LEARNING COMMUNITY (BULC) di Kota Summarecon Bekasi, dan pada tahap selanjutnya kampus Binus University akan beroperasi secara penuh pada tahun 2018.', 'A', 'SWASTA', 'pmb@binus.edu', 'binus.ac.id', '(021) 5345830', 'Jl. Raya Kb. Jeruk No.27, RW.9, Kb. Jeruk, Kec. Kb. Jeruk, Kota Jakarta Barat, Jawa Barat 11530', 38380, 'https://goo.gl/maps/PR87MyNdvk2Ejkp59', 40, 6, 'PUBLISHED', 'N', 'N', 12, 'university/logo/1575874174682-72f11709.png', 'university/banner/1575874177953-9f95b2d8.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-bina-nusantara', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(14, 'Universitas Mercu Buana', NULL, '<p>Pengusaha H. Probosutedjo (almarhum) yang mempunyai pengalaman sebagai guru di Perguruan Taman Siswa, Pematang Siantar, Sumatera Utara, pada tanggal 10 Nopember 1981 mendirikan Akademi Wiraswasta Dewantara (AWD). Peresmiannya dilakukan oleh almarhum Bapak H. Adam Malik, Wakil Presiden RI saat itu. Dewantara diambil dari nama tokoh Pendidikan Nasional, yaitu Ki Hajar Dewantara. Misi pendidikan akademi ini antara lain adalah mengembangkan model pendidikan untuk melahirkan pengusaha Pancasilais, dan kader-kader pembangunan yang mandiri serta mampu menciptakan kesempatan kerja.</p><p>Sebelum memiliki kampus sendiri, penyelenggaraan perkuliahan dilaksanakan di Gedung Yayasan Tenaga Kerja Indonesia (YTKI) Jl. Gatot Soebroto. Tahun 1984, Yayasan Menara Bhakti berhasil membangun kampus yang diberi nama Kampus Menara Bhakti yang berlokasi di Jl. Raya Meruya Selatan, Kembangan, Jakarta Barat. Pada tahun 1985, berbekal kemampuan dan pengalaman dalam menyelenggarakan pendidikan Akademi Wiraswasta Dewantara, timbul gagasan mendirikan lembaga pendidikan tingkat universitas. Dengan Surat Keputusan KetuaYayasan Menara Bhakti nomor 04/SKEP/KET/VI/1985 tanggal 12 Juni 1985, dibentuk Panitia Pendirian Universitas, dengan Ketua Dr. Sri Edi Swasono dan dibantu oleh H. Abdul Madjid (almarhum), Drs. Iman Santosa Sukardi (almarhum), Drs. M. Enoch Markum, Ir. Suharyadi, M.S.,Soekarno dan Prijo S. Parwoto (almarhum).</p><p>Setelah melalui persiapan pendirian dan studi kelayakan, dengan surat nomor 010/KET/YMB/VI/85 tanggal 12 Juni 1985, yayasan mengajukan permohonan izin mendirikan Universitas Mercu Buana (UMB) kepada Kopertis Wilayah III. Berdasarkan surat nomor/ 15/ KOP.III/S.VI/85 yang ditandatangani oleh Prof. Dr. Boesjra Zahir (almarhum), pada tanggal 18 Juni 1985, Kopertis Wilayah III menyetujui dan memberikan izin &#34;Operasional&#34; penyelenggaraan Universitas Mercu Buana.</p>', 'A', 'SWASTA', 'pmb@mercubuana.ac.id', 'mercubuana.ac.id', '(+62) 215840816\r\n(+62) 85100633360', 'Jl. Meruya Selatan No.1, RT.4/RW.1, Meruya Sel., Kec. Kembangan, Kota Jakarta Barat, Daerah Khusus Ibukota Jakarta 11650', 34998, 'https://goo.gl/maps/34AFuffnTWyW8xJh6', 40, 6, 'PUBLISHED', 'N', 'N', 13, 'university/logo/1575876698251-d87af881.png', 'university/banner/1575876702366-5e6c55ed.jpg', NULL, NULL, NULL, NULL, '[{"name":"Kampus Menteng","address":"Jl. Menteng Raya No.29, RT.2/RW.7, Kb. Sirih, Kec. Menteng, Kota Jakarta Pusat, Daerah Khusus Ibukota Jakarta 10340","phone":"(021) 31934471","fax":""},{"name":"Kampus Jatisampurna","address":"Jl. Raya Kranggan No.6, RT.006/RW.008, Jatiraden, Kec. Jatisampurna, Kota Bks, Jawa Barat 17433","phone":"(021) 8449635","fax":""},{"name":"Kampus Warung Buncit","address":"Jl. Warung Buncit Raya No.98, RT.1/RW.7, Pejaten Bar., Kec. Ps. Minggu, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12510","phone":"0817-7663-1933","fax":""}]', 'universitas-mercu-buana', '2019-12-06 05:23:33', '0', '2019-12-10 02:21:34', '0', NULL, NULL),
	(15, 'Universitas Bunda Mulia', 'UBM', 'Cikal bakal Universitas Bunda Mulia  adalah dari dua sekolah tinggi yang dikelola oleh Yayasan Pendidikan Bunda Mulia, yaitu Sekolah Tinggi Manajemen Informatika dan Komputer (STMIK) dan Sekolah tinggi Ilmu Ekonomi (STIE) Bunda Mulia.\n\nBermula dari Akademi Manajemen Informatika dan Komputer (AMIK) Bunda Mulia yang didirikan dengan Akta Notaris Mohamad Said Tadjoedin no.108 tanggal 11 Desember 1986. AMIK Bunda Mulia berdiri berdasarkan Surat Keputusan Mendikbud No. 183/O/1987 tanggal 30 Maret 1987 untuk program studi Manajemen dengan jenjang pendidikan Diploma Tiga (D-III).\n\nPada tahun 1995 berdasarkan SK Dirjen Dikti No.429/Dikti/Kep/1995 tanggal 10 Oktober 1995 AMIK berubah bentuk menjadi Sekolah Tinggi Manajemen dan Komputer Bunda Mulia (STMIK Bunda Mulia). Seiring dengan perkembangan di lingkungan Bunda Mulia, dan juga kepercayaan dari masyarakat dan pemerintah, maka STMIK Bunda Mulia berubah menjadi Universitas Bunda Mulia dengan dikeluarkannya SK Menteri Pendidikan Nasional No. 73/D/O/2003 pada tanggal 10 Juni 2003, yang memuat mengenai pemberian ijin penggabungan Sekolah Tinggi Manajemen Informatika dan Komputer (STMIK) dan Sekolah Tinggi Ilmu Ekonomi (STIE) serta penambahan program-program studi baru menjadi Universitas Bunda Mulia.', 'B', 'SWASTA', 'info@ubm.ac.id', 'www.ubm.ac.id', '(021) 690 9090', 'Jl. Lodan Raya No.2, RT.12/RW.2, Ancol, Kec. Pademangan, Kota Jkt Utara, Daerah Khusus Ibukota Jakarta 14430', 5680, 'https://goo.gl/maps/EiKGKFE8W6jkh3Kn8', 44, 6, 'PUBLISHED', 'N', 'N', 14, 'university/logo/1575876970842-c4c02285.png', 'university/banner/1575876974318-8ad1aa20.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-bunda-mulia', '2019-12-06 05:23:33', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(16, 'Universitas Bina Sarana Informatika', 'BSI', 'Perubahan Akademi Bina Sarana Informatika (BSI) menjadi Universitas Bina Sarana Informatika (UBSI) telah diresmikan. Penyerahan Surat Keputusan Perubahan Akademi BSI menjadi Universitas Bina Sarana Informatika (UBSI) ini berlangsung di BSI Convention Center, Jalan Raya Kaliabang nomor 8, Perwira, Bekasi Utara, Bekasi, Jawa Barat.\n\nSurat Keputusan tersebut diserahkan langsung oleh Sekretaris Jenderal Kementrian Riset, Teknologi dan Pendidikan Tinggi, Prof Ainun Na’im PhD, MBA, kepada Pengurus Yayasan Bina Sarana Informatika, Efriadi Salim yang didampingi Direktur BSI Naba Aji Notoseputro. Kegiatan ini dilakukan bersamaan dengan rangkaian kegiatan seminar motivasi BSI dan disaksikan langsung oleh 9 ribu mahasiswa baru BSI tahun ajaran 2018/2019.\n\nPenyerahan Surat Keputusan tersebut dihadiri pula oleh Direktur Jenderal Pembelajaran dan Kemahasiswaan, Prof Intan Ahmad PhD; Kepala Lembaga Layanan Pendidikan Tinggi Wilayah III DKI Jakarta, Dr Ir Ilah Sailah MS; Sekretaris Lembaga Layanan Pendidikan Tinggi Wilayah III DKI Jakarta, Dr M Samsuri SPd, MT; serta wakil direktur BSI, ketua Program Studi di BSI, beserta jajaran pimpinan BSI lainnya.\n\nDirektur BSI, Naba Aji Notoseputro mengatakan, perubahaan dari Akademi BSI menjadi UBSI tersebut prosesnya sudah cukup lama dilaksanakan. “Perubahan dilakukan sebagai salah satu kesiapan BSI untuk menghadapi era disruptif,” kata Naba Aji dalam rilis yang diterima.\n\nIa menambahkan, sudah 30 tahun lamanya BSI eksis di dunia pendidikan tinggi. Tentunya perkembangan tersebut membuat BSI menjadi salah satu perguruan tinggi terbesar. BSI memiliki enam akademi, 25 lima kampus se-Indonesia dan kurang lebih 20 ribu mahasiswa aktif. “Pihak Yayasan Bina Sarana Informatika berinisiatif untuk menyatukan 21 kampus yang dimiliki oleh BSI menjadi satu universitas besar,”\n\nPerubahan menjadi universitas tersebut juga sebagai salah satu langkah BSI menjadi perguruan tinggi terbesar dengan akreditasi baik. Selain itu juga sebagai upaya BSI dalam meningkatkan kualitas sistem pendidikan serta kompetensi lulusannya. Mahasiswa yang berada di daerah maupun di ibukota akan merasakan hak yang sama, baik dari sistem pembelajaran, pengembangan kompetensi, hingga kesempatan berkarir yang akan dimiliki oleh lulusan UBSI.\n\n“Perubahan menjadi universitas ini, akan memberikan manfaat kepada seluruh civitas BSI, baik mahasiswa, dosen maupun lulusannya. Seperti, mahasiswa diploma tiga akan lebih mudah untuk melanjutkan pendidikannya pada tingkat Strata Satu. Karena ke depannya Universitas BSI akan memiliki 4 fakultas, yakni Fakultas Tenik, Fakultas Teknologi Informasi, Fakultas Komunikasi dan Bahasa serta Fakultas Ekonomi dan Bisnis,”\n\nDari empat fakultas tersebut, Universitas Bina Sarana Informatika (UBSI) memiliki 19 (sembilan belas) program studi, yakni Teknik Elektro, Teknik Industri, Sastra Inggris, Komputerisasi Akuntansi, Manajemen Informatika, Sekretari, Manajemen Administrasi, Bahasa Inggris, dan Periklanan.\n\nSelain itu, Prodi Hubungan Masyarakat, Penyiaran, Manajemen Perpajakan, Akuntansi, Sistem Informasi, Teknik Informatika, Manajemen, Ilmu atau Sains Komunikasi, Teknologi Informasi, dan Rekayasa Perangkat Lunak.', 'B', 'SWASTA', 'Hallobsi@bsi.ac.id', 'www.bsi.ac.id', '(021) 80 000 63', 'Jl. Kamal Raya No.18, RT.6/RW.3, Cengkareng Bar., Kecamatan Cengkareng, Kota Jakarta Barat, Daerah Khusus Ibukota Jakarta 11730', 43497, 'https://goo.gl/maps/eSmXTdXqftFwAZPq7', 40, 6, 'PUBLISHED', 'N', 'N', 15, 'university/logo/1575877378033-a054a5dc.png', 'university/banner/1575877384370-df2571eb.png', NULL, NULL, NULL, NULL, '[{"name":"UBSI CILEDUG","address":"Jalan Ciledug Raya No.168, Ulujami, Pesanggrahan, RT.8/RW.4, Ulujami, Kec. Pesanggrahan, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12250","phone":"(021) 7365715","fax":""},{"name":"UBSI SALEMBA 22","address":"Jalan Salemba Tengah No.22, RT.14/RW.3, Paseban, Senen, RT.14/RW.3, Paseban, Kec. Senen, Kota Jakarta Pusat, Daerah Khusus Ibukota Jakarta 10440","phone":"(021) 3157230","fax":""},{"name":"UBSI SALEMBA 45","address":"Jalan Salemba Tengah No.45, RT.14/RW.3, Paseban, Senen, RT.14/RW.3, Paseban, Kec. Senen, Kota Jakarta Pusat, Daerah Khusus Ibukota Jakarta 10440","phone":"(021) 3157230","fax":""},{"name":"UBSI PEMUDA","address":"Jl. Kayu Jati V No.2, RT.9/RW.5, Rawamangun, Kec. Pulo Gadung, Kota Jakarta Timur, Daerah Khusus Ibukota Jakarta 13220","phone":"(021) 29385139","fax":""},{"name":"UBSI KALIMALANG","address":"Jl. SMA Kapin No.292A, RT.9/RW.8, Pondok Kelapa, Duren Sawit, RT.9/RW.8, Pd. Klp., Kec. Duren Sawit, Kota Jakarta Timur, Daerah Khusus Ibukota Jakarta 13450","phone":"(021) 86906400","fax":""},{"name":"UBSI JATIWARINGIN","address":"Jalan Jatiwaringin Raya No.18, RT.5/RW.3, Jatiwaringin, Makasar, RT.5/RW.5, Cipinang Melayu, Kec. Makasar, Kota Jakarta Timur, Jawa Barat 13620","phone":"(021) 80 000 63","fax":""},{"name":"UBSI KALIABANG","address":"Jl. Kaliabang No.67, Perwira, Kec. Bekasi Utara, Kota Bks, Jawa Barat 17124","phone":"(021) 88985613","fax":""},{"name":"UBSI BEKASI","address":"Jl. Cut Mutia No.88, Sepanjang Jaya, Kec. Rawalumbu, Kota Bks, Jawa Barat 17113","phone":"(021) 82425634","fax":""},{"name":"UBSI DEWI SARTIKA","address":"Jl. Dewi Sartika No.289, RT.4/RW.5, Cawang, Kec. Kramat jati, Kota Jakarta Timur, Daerah Khusus Ibukota Jakarta 13630","phone":"(021) 8010827","fax":""},{"name":"UBSI WARUNG JATI","address":"Jl. Damai No. 8, Warung Jati Barat, Margasatwa, RT.1/RW.1, Ragunan, Kec. Ps. Minggu, Kota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 12450","phone":"(021) 78839513","fax":""},{"name":"UBSI BOGOR","address":"Jl. Merdeka No.168, Ciwaringin, Kecamatan Bogor Tengah, Kota Bogor, Jawa Barat 16124","phone":"(0251) 8353009","fax":""}]', 'universitas-bina-sarana-informatika', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(17, 'Universitas Esa Unggul', NULL, 'Universitas Esa Unggul (UEU) didirikan pada tahun 1993 di bawah naungan Yayasan Pendidikan Kemala Mencerdaskan Bangsa adalah Perguruan Tinggi Swasta terkemuka dan menjadi salah satu Universitas Swasta terbaik di Indonesia yang memiliki VISI, yaitu Menjadi perguruan tinggi kelas dunia berbasis intelektualitas, kreatifitas dan kewirausahaan yang unggul dalam mutu pengelolaan (proses) dan hasil (output) kegiatan Tri Dharma Perguruan Tinggi.  Dan memiliki MISI: Menyelenggarakan pendidikan yang bermutu dan relevan, Menciptakan suasana akademik yang kondusif, Menciptakan pemimpin yang berkarakter dan berdaya saing tinggi.\n\nDalam satu dekade terakhir ini UEU mengalami perkembangan yang sangat pesat menjadi salah satu Perguruan Tinggi Swasta (PTS) terkemuka di Jakarta.  Sejarah mencatat bahwa UEU adalah Perguruan Tinggi yang merintis dan mempelopori pendirian Akademi Rekam Medik (ARM) dan Program Sarjana Terapan Fisioterapi yang pertama di Indonesia.  Program peningkatan kualitas akademik mahasiswa dan dosen, pelayanan, sarana dan prasarana, penelitian dan pengabdian masyarakat serta kualitas lulusan menjadi prioritas utama untuk mencapai a World Class University.  Namun, tantangan lingkungan strategik juga  menuntut UEU untuk selalu melakukan penyesuaian dan inovasi pada nilai-nilai, budaya kerja dan etos kerjanya menjadi perguruan tinggi kelas dunia, berarti UEU bertekad untuk mengacu pada standar perguruan tinggi kelas dunia dan menjalankan best practices yang dilakukan oleh perguruan tinggi kelas dunia.\n\nUEU berupaya menghasilkan output, baik hasil penelitian maupun hasil pengabdian masyarakat, yang diakui kontribusinya oleh komunitas internasional.  Dan yang paling penting UEU berupaya keras untuk menghasilkan lulusan yang mempunyai kompetensi dan berdaya saing global.  Kewirausahaan dan kreatifitas, yang secara eksplisit telah dijadikan spirit dan tema utama akan mewarnai seluruh perjalanan kemajuan menjelang 25 (dua puluh lima) tahun berdirinya UEU sampai dengan tahun – tahun berikutnya.\n\nUEU dikenal bukan hanya menghasilkan pemikir cerdas dan kritis, namun juga menghasilkan lulusan yang inovatif dan mampu menciptakan lapangan pekerjaan. UEU mengembangkan dan menjalin kerjasama dengan berbagai pihak baik institusi nasional maupun internasional dengan Universitas dan Program Studi untuk meningkatkan kualitas pembelajaran, kurikulum, dan mutu lulusan UEU, sehingga memiliki ketrampilan dan kompetensi terbaik sesuai dengan bidangnya.\n\nLokasi UEU berada di daerah yang strategis pada kawasan pendidikan tinggi di  wilayah Jakarta Barat. Kampus yang berlokasi di sisi Tol Tomang – Kebon Jeruk mudah dicapai dari seluruh penjuru Jakarta, Tangerang, Bekasi, Bogor dan sekitarnya. Dengan areal kampus hijau seluas 4,5 ha di jantung kota Jakarta, UEU terus berkembang sebagai “Urban Campus” yang menjadi kebanggaan masyarakat.', 'B', 'SWASTA', 'pmb@esaunggul.ac.id', 'www.esaunggul.ac.id', '081290073636 / 081390073335', 'Jl. Arjuna Utara No.9, RT.1/RW.2, Duri Kepa, Kec. Kb. Jeruk, Kota Jakarta Barat, Daerah Khusus Ibukota Jakarta 11510', 14583, 'https://goo.gl/maps/C9HxjpTgV8brhNTXA', 40, 6, 'PUBLISHED', 'N', 'N', 16, 'university/logo/1575878569408-347dca96.png', 'university/banner/1575878573531-819bcad5.jpg', NULL, NULL, NULL, NULL, '[{"name":"Kampus Tangerang","address":"Jalan Citra Raya Boulevard – Ecopolis SA Blok VD. 02, Citra Raya, Tangerang","phone":"(021) 22596025, 22596026","fax":""},{"name":"Kampus Bekasi","address":"Komplek Office Park Blok 5 No. 11 – 17 , Jl. Boulevard Raya – Kota Harapan Indah  (Samping Kantor Camat Medan Satria – Bekasi)","phone":"021 88381493, 021 88381494","fax":""},{"name":"Kampus Internasional","address":"Jl. Raya Legok – Karawaci, Curug Sangereng, Klp. Dua, Tangerang, Banten 15810  (Majestic Point Serpong)","phone":"(021) 55683700","fax":""}]', 'universitas-esa-unggul', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(18, 'Universitas Swiss German', 'SGU', 'Didirikan pada tahun 2000, Swiss German University (SGU) merupakan perintis universitas internasional di Indonesia. Dibentuk melalui kerjasama antara Indonesia, Swiss, Jerman, dan Austria, Swiss German University (SGU) menggebrak dunia pendidikan dengan visi & misi membawa pengetahuan dan teknologi Indonesia ke level yang lebih tinggi lagi. Kehadirannya pun langsung disambut dengan antusias terutama oleh para masyarakat yang ingin merasakan sensasi berkuliah dengan atmosfir seperti di luar negeri.\n\nTidak hanya memberikan suasana berkuliah di luar negeri dari segi arsitektur dan ruangan, dalam bahasa percakapan dan buku tekstual, Swiss German University (SGU) pun menggunakan bahasa internasional. Jadi tiap-tiap ruang belajar pada setiap mata perkuliahan menggunakan Bahasa Inggris sebagai bahasa pengantar dan bahasa sehari-hari antara dosen dan mahasiswanya. Ini berlaku untuk semua jurusan yang terdapat dalam Swiss German University (SGU); syarat mutlak dan utama untuk sebuah Perguruan Tinggi atau Universitas yang menyandang gelar internasional di Indonesia.', 'B', 'SWASTA', 'info@sgu.ac.id', 'www.sgu.ac.id', '0811 8010 600', 'The Prominence Tower Alam Sutera, Jl. Jalur Sutera Bar. No.Kav 15, RT.003/RW.006, Panunggangan Tim., Kec. Pinang, Kota Tangerang, Banten 15143', 805, 'https://goo.gl/maps/aKSALXCsiv6X9ZjM6', 23, 3, 'PUBLISHED', 'N', 'N', 17, 'university/logo/1575879897706-cfed5bc4.png', 'university/banner/1575879901277-7a043abc.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-swiss-german', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(19, 'Universitas Bung Karno', 'UBK', 'Universitas Bung Karno adalah universitas swasta yang bertempat di Jakarta Pusat, Indonesia. Nama universitas ini diambil dari nama Proklamator Kemerdekaan Indonesia, Ir. Soekarno dikenal juga dengan nama panggilan Bung Karno. Universitas ini didirikan oleh Yayasan Pendidikan Soekarno pada tahun 1999 dan diresmikan oleh Presiden RI ketiga, Prof. Dr. Ing. B.J. Habibie di Istana Presiden.', 'B', 'SWASTA', 'info@ubk.ac.id', 'www.ubk.ac.id', '(021) 3929591', 'Jl. Pegangsaan Timur No.17A, Pegangsaan, Menteng, RT.1/RW.1, RT.1/RW.1, Pegangsaan, Kec. Menteng, Kota Jakarta Pusat, Daerah Khusus Ibukota Jakarta 10310', 5702, 'https://goo.gl/maps/rQRVTtYE8u6Ap6BG8', 41, 6, 'PUBLISHED', 'N', 'N', 21, 'university/logo/1575884150837-9200ae53.jpg', 'university/banner/1575884153818-793a1e9f.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-bung-karno', '2019-12-06 05:23:34', '0', '2019-12-09 09:38:08', '0', NULL, NULL),
	(20, 'Universitas Kristen Indonesia', 'UKI', 'Tidak lama setelah kemerdekaan Republik Indonesia (1945), beberapa tokoh nasional yang juga adalah pemuka-pemuka Kristen Indonesia tergerak dan merasa perlu untuk mendirikan Dewan Gereja di Indonesia (DGI). Harapan tersebut baru terlaksana pada tanggal 25 Mei 1950. Di awal kegiatannya, lembaga ini juga telah memberikan perhatian yang cukup besar pada masalah pendidikan karena saat itu bangsa Indonesia sangat memerlukan sumber daya manusia untuk mengisi lapangan kerja dalam berbagai aspek kehidupan. Kebutuhan ini sudah bersifat mendesak.\n\nPemikiran akan inginnya masyarakat Kristen Indonesia untuk turut berpartisipasi dalam dunia pendidikan terus berkembang dalam diskusi-diskusi yang terjadi di lembaga ini. Bahkan dipikirkan pula akan perlunya mendirikan sebuah “universiteit”. Atas dasar itulah, DGI membentuk suatu komisi yang dipimpin oleh Prof. Dr. I.P. Simanjuntak, MA. Komisi ini bertugas membuat suatu studi kelayakan untuk mendirikan universitas yang hasilnya dilaporkan kepada DGI. Sebagai tindak lanjutnya, DGI mengeluarkan resolusi mengenai Universiteit Kristen pada tanggal 30 Juni 1953. Resolusi yang ditandatangani oleh Ds. W.J. Rumambi, selaku Sekretaris Umum DGI, dalam Sidang Lengkap DGI dari tanggal 20-30 Juni 1953 mengusulkan kepada semua gereja dan masyarakat Kristen di Indonesia untuk membantu sepenuhnya pendirian Universiteit Kristen, baik secara moril maupun materil.\n\nBeranjak dari resolusi tersebut, maka tokoh-tokoh Kristen Indonesia, yakni Mr. Todung Sutan Gunung Mulia, Mr. Yap Thiam Hien, Benjamin Thomas Philip Sigar, atas nama gereja-gereja yang tergabung dalam DGI (sekarang PGI), mendirikan Yayasan Universitas Kristen Indonesia di hadapan notaris Raden Kadiman, dengan nomor akte 117, tertanggal 18 Juli 1953. Anggota Yayasan kemudian diperbesar dengan kehadiran Elviannus Katoppo, Ong Jan Hong MD, Aminudin Pohan MD, Seri Condar Nainggolan MD, Benjamin Prawirohadmodjo, Pdt. Komarlin Tjakraatmadja, Gerrit Siwabessy MD, Tan Tek Heng, dan J.C.T Simorangkir. Tiga bulan kemudian, yaitu pada tanggal 15 Oktober 1953, diresmikanlah Universitas Kristen Indonesia (UKI) yang terdiri dari:\n\nFakultas Sastra dan Filsafat, dengan Sub-fakultas: Pedagogik dan Sastra, dan Fakultas Ekonomi.\n\n Ketika itu, perkuliahan dan kegiatan administrasi masih berlangsung di gedung HSK yang terletak di Jl. Diponegoro 86, dan di tiga buah flat di Jl. Salemba 10. Dalam perjalanan pengabdiannya, didirikanlah Fakultas Hukum (1956), Fakultas Kedokteran (1962), Fakultas Teknik (1963), dan Fakultas Ilmu Sosial dan Politik (1994).\n\nHingga saat ini UKI telah memiliki 8 fakultas yang terdiri dari Fakultas Keguruan dan Ilmu Pendidikan (FKIP), Sastra (FS), Ekonomi (FE), Hukum (FH), Kedokteran (FK), Teknik (FT), Ilmu Sosial dan Ilmu Politik (FISIPOL), Fakultas Vokasi yang memiliki 3 program studi terdiri dari Fisioterapi, Keperawatan, dan Perbankan, serta Program Pascasarjana.', 'B', 'SWASTA', 'pmb@uki.ac.id', 'www.uki.ac.id', '021-8092425', 'Jl. Mayjen Sutoyo No.2, RW.6, Cawang, Kec. Kramat jati, Kota Jakarta Timur, Daerah Khusus Ibukota Jakarta 13630', 4704, 'https://goo.gl/maps/QPk1uJohwd3UQoY59', 43, 6, 'PUBLISHED', 'N', 'N', 23, 'university/logo/1575885842664-91e0b62f.png', 'university/banner/1575885846004-a74cea1e.jpg', NULL, NULL, NULL, NULL, '[{"name":"Kampus Diponegoro","address":"Jl.Diponegoro No. 84-86, Jakarta Pusat 10430","phone":"021-3920174 ","fax":""}]', 'universitas-kristen-indonesia', '2019-12-06 05:23:34', '0', '2019-12-09 10:22:30', '0', NULL, NULL),
