	(24, 'Universitas Jayabaya', NULL, NULL, 'B', 'SWASTA', 'info@jayabaya.ac.id', 'www.jayabaya.ac.id', '0851-0847-6969', 'Jl. Pulomas Selatan Kav. 23, Pulo Mas Selatan, Pulo Gadung, RT.4/RW.9, Kayu Putih, Kec. Pulo Gadung, Kota Jakarta Timur, Daerah Khusus Ibukota Jakarta 13210', 11, 'https://goo.gl/maps/fP51UB5JAyr3Lswh6', 43, 6, 'PUBLISHED', NULL, 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-jayabaya', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(25, 'Universitas Krisnadwipayana', 'UNKRIS', NULL, 'B', 'SWASTA', 'marketing@unkris.ac.id', 'unkris.ac.id', '(021) 8462230/8462231', 'Jalan Raya Jatiwaringin, RT. 03 / RW. 04, Jatiwaringin, Pondok Gede, RT.009/RW.005, Jaticempaka, Kec. Pondokgede, Kota Bks, Jawa Barat 13077', 10, 'https://goo.gl/maps/jhq2isdVi9u6yxtM7', 68, 6, 'PUBLISHED', NULL, 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-krisnadwipayana', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(26, 'Universitas Kristen Krida Wacana', 'UKRIDA', 'UKRIDA resmi berdiri pada 20 Januari 1967 berdasarkan Surat Keputusan Direktur Jenderal Pendidikan Tinggi Departemen Pendidikan dan Kebudayaan Republik Indonesia Nomor 202/DPT/I/1970.\n\nSemula berdiri dengan nama Universitas Kristen Djaya di bawah naungan Yayasan Badan Pendidikan Kristen Jawa Barat. Di awal pendiriannya UKRIDA mempunyai tiga fakultas yaitu Fakultas Kedokteran, Fakultas Teknik, dan Fakultas Ekonomi.\n\nSemula bernama Universitas Kristen Djaya dan pada 1992 berganti menjadi Universitas Kristen Krida Wacana\nBerdirinya UKRIDA merupakan prakarsa dari beberapa tokoh gereja seperti Prof. Dr. J. L. Ch. Abineno, Uripto Widjaya, Ny. Dr. Pouw Houw Tjiang, Ny. J. M. Rumambi, dr. J. Suwarno beserta D. Sutedja, Swandjaja, Kol. Dr. F. Pattiasina, dr. O. E. Engelen, Pdt. C. Suleeman, M. Th., dan Pdt. Lukito Handoyo untuk mendirikan sebuah perguruan tinggi Kristen sebagai wujud kesaksian dan pelayanan di bidang pendidikan tinggi dalam pembangunan bangsa dan negara Republik Indonesia. Prakarsa para tokoh tersebut didukung oleh Prof. Dr. Siwabessy (Menteri Kesehatan saat itu) dan Pdt. W. J. Rumambi (Menteri penerangan saat itu).\n\nKarena sebagian besar tokoh gereja pemrakarsa adalah anggota Gereja Kristen Indonesia Jawa Barat (GKI Jabar), maka Majelis Sinode GKI Jawa Barat menyambut baik prakarsa tersebut. Lewat sidangnya yang ke-23 pada 15 September 1965 memutuskan untuk mendirikan Universitas Kristen Djaya, dengan Badan Pendidikan Kristen Jawa Barat (BPK Jakbar) sebagai pengelolanya.\n\nGedung Kampus di Tanjung DurenGedung Kampus di Tanjung Duren Universitas Kristen Djaya tumbuh dan berkembang dalam dinamika yang timbul tenggelam, melalui berbagai tantangan dan hambatan, Hanya karena berkat Tuhan jualah, penyelenggara UKRIDA akhirnya mampu mengemban tanggung jawab dalam mewujudkan cita kesaksian dan pelayanan Kristiani di bidang pendidikan tinggi.\n\nSejak tahun 1985, UKRIDA diperkenankan olehNya pindah dari Kampus Gunung Sahari ke Kampus Tanjung Duren. Enam tahun berselang yakni pada 1991, penyelenggaraan UKRIDA dialihkan dari Yayasan Badan Pendidikan Kristen Jawa Barat kepada Yayasan Pendidikan Tinggi Kristen Krida Wacana.\n\nUniversitas Kristen Krida Wacana berarti Universitas yang Berkarya bagi Sang Firman (Tuhan) Perubahan nama juga dilakukan pada 8 Februari 1992. Universitas Kristen Djaya resmi berganti nama menjadi Universitas Kristen Krida Wacana berdasarkan SK Menteri Pendidikan dan Kebudayaan RI No. 0106/0/1992, dengan tetap menggunakan akronim UKRIDA. Arti kata Krida adalah berkarya, sedangkan Wacana berarti Firman (Tuhan). Universitas Kristen Krida Wacana berarti Universitas yang Berkarya bagi Sang Firman (Tuhan).\n\nSeiring kebutuhan akan program studi baru, UKRIDA pada 1999 membuka program S2 Magister Manajemen, dan pada 2002 juga membuka Program Studi S1 Teknik Informatika dan S1 Psikologi. Program Studi S1 Sistem Informasi dan S1 Sastra Inggris adalah dua yang terakhir dibuka pada 2009 dan 2014.\n\nKampus II UKRIDAKampus II UKRIDA\nPada 3 Agustus 2002, UKRIDA meresmikan kampus II di jalan Terusan Arjuna Utara No. 6, yang ditempati oleh Fakultas Kedokteran. Kampus III yang berlokasi di Kelapa Gading juga dibuka 2010 untuk perkuliahan Fakultas Ekonomi.\n\nUKRIDA bercita-cita menjadi lembaga yang mantap dan dapat memberikan yang terbaik bagi Tuhan dan bangsa. UKRIDA ingin menjadi partner setiap peserta didik, menatap masa depan dengan senantiasa memperbaiki diri, memperbaiki fasilitas layanan, dan meningkatkan kapabilitas. Harapan ini dilandasi MOTO kehidupan UKRIDA yaitu "Being Transformed to Win The Future".', 'C', 'SWASTA', 'admisi@ukrida.ac.id', 'www.ukrida.ac.id', '021 566 6952', 'Kampus I\r\nJl. Tanjung Duren Raya no. 4, Jakarta Barat', 4130, 'https://goo.gl/maps/kiw6EZ6881REdUPx6', 40, 6, 'PUBLISHED', 'N', 'N', 18, 'university/logo/1575880286532-a251de2f.jpg', 'university/banner/1575880290605-255a99fa.jpg', NULL, NULL, NULL, NULL, '[{"name":"Kampus II","address":"Jl. Arjuna Utara no. 6, Jakarta Barat","phone":"021 5694 2061","fax":"021 563 1731"},{"name":"Kampus III","address":"Kokan Permata Blok A no. 6-8, Jl. Boulevard Bukit Gading Raya, Kelapa Gading – Jakarta Utara ","phone":"021 294 50 999 ","fax":"021 294 51 374"}]', 'universitas-kristen-krida-wacana', '2019-12-06 05:23:34', '0', '2019-12-09 09:42:06', '0', NULL, NULL),
	(27, 'Universitas Muhammadiyah Jakarta', 'UMJ', NULL, 'B', 'SWASTA', 'info@umj.ac.id', 'umj.ac.id', '021-7492862\r\n081370881955', 'Jl. KH. Ahmad Dahlan, Ciputat, Cireundeu, Ciputat Timur\r\nKota Jakarta Selatan, Daerah Khusus Ibukota Jakarta 15419', 23, 'https://goo.gl/maps/22nJYwbVfVk3JsCz7', 42, 6, 'PUBLISHED', NULL, 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-muhammadiyah-jakarta', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
