	(29, 'Universitas Pancasila', NULL, NULL, 'A', 'SWASTA', 'registrasi@univpancasila.ac.id', 'www.univpancasila.ac.id', '021 78880305\r\n021 7874344\r\n021 98880038\r\n021 7270086', 'Jalan Srengseng Sawah, Jagakarsa, Jakarta Selatan - 12640', 15, 'https://goo.gl/maps/CAvCFugCk1mmCSMXA', 42, 6, 'PUBLISHED', NULL, 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-pancasila', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(30, 'Universitas Prof Dr Moestopo (Beragama)', NULL, NULL, 'B', 'SWASTA', 'pmb@moestopo.ac.id', 'moestopo.ac.id', '(021) 7220269, (021) 7252225', '3, Jalan Hang Lekir I 8, RT.1/RW.3, Gelora, Kecamatan Tanah Abang, Kota Jakarta Pusat, Daerah Khusus Ibukota Jakarta 10270', 7, 'https://goo.gl/maps/4aK4NUXYe9wXYCGN9', NULL, 6, 'PUBLISHED', NULL, 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-prof-dr-moestopo-beragama', '2019-12-06 05:23:34', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
	(31, 'Universitas Tarumanagara', 'UNTAR', 'Pada tahun 1959, berdirinya Yayasan Tarumanagara pada 18 Juni 1959. Berdirinya Perguruan Tinggi Ekonomi Tarumanagara, Jurusan Ekonomi Perusahaan, sebagai cikal bakal Universitas Tarumanagara.\n\nPada tahun 1962, Berdirinya Sekolah Kejuruan Teknik Arsitektur pada 1 Oktober 1962. Kemudian sekolah ini menjadi Fakultas Teknik Jurusan Arsitektur. Dan kini merupakan salah satu Jurusan Teknik Arsitektur Swasta tertua di Indonesia. Berdirinya Fakultas Ekonomi, Fakultas Hukum, Fakultas Teknik Arsitektur dan Fakultas Bahasa Inggris. Kemudian fakultas – fakultas itu membentuk Universitas Tarumanagara\n\nTahun 1965, sejalan dengan komitmen pendirian Yayasan Tarumanagara yang bergerak pada bidang pendidikan dan kesehatan, didirikanlah Fakultas Kedokteran pada 1 Oktober 1965\n \n\nTahun 1966, gejolak politik terkait G-30-S/PKI membuat perkuliahan tidak berjalan lancar. Fakultas Bahasa Inggris terpaksa ditutup dan mahasiswanya disalurkan ke Fakultas Sastra, Universitas Indonesia.\n\nPada tahun 1967 merupakan awal kebangkitan kembali UNTAR. Saat itu diresmikan penggunaan kampus Jalan S. Parman dengan upacara yang cukup meriah pada waktu itu. Peresmian itu dihadiri Wakil Gubernur DKI Jakarta Bapak Dr. R. Soewondo, yang kemudian pada tahun 1974 menjabat sebagai Ketua Yayasan Tarumanagara.', 'A', 'SWASTA', 'humas@untar.ac.id', 'untar.ac.id', '8117579727', 'Letjen S. Parman St No.1, RT.6/RW.16, Tomang, Grogol petamburan, West Jakarta City, Jakarta 11440', 14760, 'https://goo.gl/maps/DsSQHgmRZvNMSgpJA', 40, 6, 'PUBLISHED', 'N', 'N', 19, 'university/logo/1575882281989-7050709e.jpg', 'university/banner/1575882289772-98b571c7.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-tarumanagara', '2019-12-06 05:23:34', '0', '2019-12-09 09:19:42', '0', NULL, NULL),
	(32, 'Universitas Trisakti', NULL, 'Universitas Trisakti, pada tahap awal, sebagai "Entry Point" telah berhasil dan akan selalu berdiri di depan "To Stay Ahead". Lebih jauh, Universitas Trisakti telah mencoba dan berupaya mengantisipasi permasalahan di atas dengan mengembangkan Program Pascasarjana di mana upaya ini merupakan untuk pertamakalinya sebuah Perguruan Tinggi Swasta (PTS) di Indonesia yang diberikan kepercayaan penuh untuk menyelenggarakan Program Studi Magister Manajemen dengan diberikannya akreditasi penuh oleh Departemen Pendidikan dan Kebudayaan Republik Indonesia pada tanggal 16 Oktober 1992. Keberhasilan ini berlanjut dengan diberikannya akreditasi penuh untuk penyelenggaraan Program Studi Magister Teknik Sipil dan Program Studi Magister Teknik Elektro tanggal 16 Agustus 1993, serta program Magister Ilmu Kedokteran Gigi tanggal 14 Oktober 1998, Program Studi Magister Arsitektur tanggal 6 Juni 2000, Program Doktor Bidang Ekonomi tanggal 23 Juni 2000.', 'A', 'SWASTA', 'humas@trisakti.ac.id', 'mm.trisakti.ac.id', 'WA 0821-1000-2227\r\n021-5663232 ext 8178', 'Gedung Syarief Thayeb\r\nKampus A Universitas Trisakti\r\nJl. Kyai Tapa No.1, Grogol Jakarta 11440', 23816, 'https://goo.gl/maps/eA9LQvxo3AAmvWUE7', 40, 6, 'PUBLISHED', 'N', 'N', 20, 'university/logo/1575883527719-c059c27a.png', 'university/banner/1575883533035-203bca6e.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-trisakti', '2019-12-06 05:23:34', '0', '2019-12-09 09:43:59', '0', NULL, NULL),
