	(502, 'Universitas Padjadjaran', 'UNPAD', 'Universitas Padjadjaran merupakan perguruan tinggi negeri di Bandung, Jawa Barat, Indonesia dan berdiri pada tanggal 11 September 1957. Mempunyai 2(dua) kampus utama di Kampus Iwa Koesoemasoemantri di Dipati Ukur Bandung dan Kampus Jatinagor, Kabupaten Sumedang.\n\nPada 20 Oktober 2014, UNPAD berubah status menjadi Perguruan Tinggi Negeri Badan Hukum (PTN BH) dari Badan Layanan Umum (BLU). Peresmian itu ditandai dengan peraturan pemerintah (PP) yang ditandatangani mantan Presiden Susilo Bambang Yudhoyono. Penetapan itu didasarkan atas evaluasi kinerja yang dilakukan tim independen yang dibentuk Kementerian Pendidikan dan Kebudayan (Kemendikbud). Selain itu berdasarkan Keputusan Badan Akreditasi Nasional Perguruan Tinggi (BAN PT) yang ditetapkan pada 16 Januari 2014, Unpad mendapat peringkat akreditasi A (sangat baik).', 'A', 'NEGERI', 'humas@unpad.ac.id', 'www.unpad.ac.id', '022-84288888', 'Jl. Raya Bandung Sumedang KM.21, Hegarmanah, Kec. Jatinangor, Kabupaten Sumedang, Jawa Barat 45363', 32, 'https://goo.gl/maps/2AJq5hdw2nn9gfaGA', 87, 9, 'PUBLISHED', 'N', 'N', 24, 'university/logo/1575945137011-0917bb49.png', 'university/banner/1575945140254-e9f776cd.jpg', NULL, NULL, NULL, NULL, '[]', 'universitas-padjadjaran', '2019-12-06 05:24:00', '0', '2019-12-10 02:46:32', '0', NULL, NULL),
	(503, 'Universitas Pendidikan Indonesia', 'UPI', NULL, 'A', 'NEGERI', 'sekuniv_upi@upi.edu', 'www.upi.edu', '022-2013163', 'Jl. Dr. Setiabudhi No. 229 Bandung', 35, 'https://goo.gl/maps/3e5w37J1YQCMXEW37', NULL, 9, 'PUBLISHED', NULL, 'N', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'universitas-pendidikan-indonesia', '2019-12-06 05:24:00', '0', '2019-12-09 08:47:58', '0', NULL, NULL),
